mapper.select:
SELECT 
FROM bt_dc_document_library
WHERE library_id = #{libraryId}

    AND tenant_id = #{tenantId}

  AND status_cd = '00A'

SELECT 
FROM bt_dc_document_library
WHERE library_id = #{libraryId}

    AND (tenant_id = #{tenantId} or is_builtin='T')


    AND space_id = #{spaceId}

  AND status_cd = '00A'

SELECT l.library_id, l.library_name, l.description, l.library_icon, l.visibility_scope, l.creator_id AS "creatorUserId", l.owner_id AS "ownerUserId", l.created_time, l.updated_time, l.last_access_time, l.color, l.space_id, l.tenant_id, COALESCE(m.member_count, 0) AS "memberCount", COALESCE(docs.doc_count, 0) AS "documentCount", -- 跨数据库兼容：用 1/0 代替 true/false CASE WHEN me.permission_id IS NOT NULL THEN 1 ELSE 0 END AS "isSharedToMe", me.granted_by AS "sharedByUserId", CASE WHEN me.permission_type IS NOT NULL THEN me.permission_type
WHEN orgp.permission_type IS NOT NULL THEN orgp.permission_type
WHEN l.owner_id = #{param.userId} THEN 'MANAGE' WHEN l.visibility_scope = 'PUBLIC' THEN 'READ' ELSE NULL END AS "permissions" FROM bt_dc_document_library l LEFT JOIN ( SELECT lp.library_id, COUNT(DISTINCT lp.subject_id) AS member_count FROM bt_dc_library_permission lp WHERE lp.status_cd = #{param.statusCd} GROUP BY lp.library_id ) m ON m.library_id = l.library_id LEFT JOIN ( SELECT d.library_id, COUNT(*) AS doc_count FROM bt_dc_document d WHERE d.status_cd = #{param.statusCd} GROUP BY d.library_id ) docs ON docs.library_id = l.library_id LEFT JOIN bt_dc_library_permission me ON me.library_id = l.library_id AND me.status_cd = #{param.statusCd} AND me.subject_type = 'USER' AND me.subject_id = #{param.userId}
LEFT JOIN bt_dc_library_permission orgp ON orgp.library_id = l.library_id AND orgp.status_cd = #{param.statusCd} AND orgp.subject_type = 'ORG' AND orgp.subject_id IN #{oid}
WHERE l.status_cd = #{param.statusCd} and (l.is_builtin is null or (l.library_name != '我的文档' and l.is_builtin='T'))
AND l.tenant_id = #{param.tenantId}
AND l.space_id = #{param.spaceId}
AND ( l.visibility_scope = 'PUBLIC' OR ( l.visibility_scope = 'MEMBERS' AND ( l.owner_id = #{param.userId} OR me.permission_id IS NOT NULL
OR orgp.permission_id IS NOT NULL
) ) )
AND l.library_name LIKE
#{param.keywordLike}
ORDER BY l.updated_time ASC
ORDER BY l.updated_time DESC
ORDER BY l.created_time ASC
ORDER BY l.created_time DESC

SELECT l.library_id, l.library_name, l.description, l.library_icon, l.visibility_scope, l.creator_id AS "creatorUserId", l.owner_id AS "ownerUserId", l.created_time, l.updated_time, l.last_access_time, l.color, l.space_id, l.tenant_id, COALESCE(m.member_count, 0) AS "memberCount", COALESCE(docs.doc_count, 0) AS "documentCount", -- Oracle 不支持 true/false 字面量，这里改为 0（MyBatis 可映射为 Boolean） 0 AS "isSharedToMe", NULL AS "sharedByUserId", 'MANAGE' AS "permissions" FROM bt_dc_document_library l LEFT JOIN ( SELECT lp.library_id, COUNT(DISTINCT lp.subject_id) AS member_count FROM bt_dc_library_permission lp WHERE lp.status_cd = #{param.statusCd} GROUP BY lp.library_id ) m ON m.library_id = l.library_id LEFT JOIN ( SELECT d.library_id, COUNT(*) AS doc_count FROM bt_dc_document d WHERE d.status_cd = #{param.statusCd} GROUP BY d.library_id ) docs ON docs.library_id = l.library_id WHERE l.status_cd = #{param.statusCd} and (l.is_builtin is null or (l.library_name != '我的文档' and l.is_builtin='T'))
AND l.space_id = #{param.spaceId}
AND l.tenant_id = #{param.tenantId}
AND l.library_name LIKE
#{param.keywordLike}
ORDER BY l.updated_time ASC
ORDER BY l.updated_time DESC
ORDER BY l.created_time ASC
ORDER BY l.created_time DESC

SELECT l.library_id, l.library_name, l.description, l.library_icon, l.color, l.visibility_scope, l.creator_id AS "creatorUserId", l.created_time, l.updated_time, l.space_id, l.tenant_id, COALESCE(m.member_count, 0) AS "memberCount", COALESCE(docs.doc_count, 0) AS "documentCount", CASE WHEN me.permission_type IS NOT NULL THEN me.permission_type WHEN l.owner_id = #{userId} THEN 'MANAGE' WHEN l.visibility_scope = 'PUBLIC' THEN 'READ' ELSE NULL END AS "permissions", -- Oracle 不支持 true/false 字面量，改为 1/0（MyBatis 可映射为 Boolean） CASE WHEN uf.target_id IS NOT NULL THEN 1 ELSE 0 END AS "isFavorite" FROM bt_dc_document_library l LEFT JOIN ( SELECT lp.library_id, COUNT(DISTINCT lp.subject_id) AS member_count FROM bt_dc_library_permission lp WHERE lp.status_cd = #{statusCd} GROUP BY lp.library_id ) m ON m.library_id = l.library_id LEFT JOIN ( SELECT d.library_id, COUNT(*) AS doc_count FROM bt_dc_document d WHERE d.status_cd = #{statusCd} GROUP BY d.library_id ) docs ON docs.library_id = l.library_id LEFT JOIN bt_dc_library_permission me ON me.library_id = l.library_id AND me.status_cd = #{statusCd} AND me.subject_type = 'USER' AND me.subject_id = #{userId} LEFT JOIN bt_dc_user_favorite uf ON uf.target_id = l.library_id AND uf.target_type = 'LIBRARY' AND uf.user_id = #{userId} AND uf.status_cd = #{statusCd} WHERE l.status_cd = #{statusCd} AND l.library_id = #{libraryId}
AND l.tenant_id = #{tenantId}
AND l.space_id = #{spaceId}

mapper.update:
UPDATE bt_dc_document_library
SET library_name = #{libraryName},
    description = #{description},
    library_icon = #{libraryIcon},
    color = #{color},
    updator_id = #{updatorId},
    updated_time = #{updatedTime}
WHERE library_id = #{libraryId}
  AND space_id = #{spaceId}
  AND status_cd = '00A'

UPDATE bt_dc_document_library
SET visibility_scope = #{visibilityScope},
    updator_id = #{updatorId},
    updated_time = #{updatedTime}
WHERE library_id = #{libraryId}
  AND space_id = #{spaceId}
  AND status_cd = '00A'

