FROM bt_dc_document_library
WHERE id = #{id}

  AND tenant_id = #{tenantId}

  AND status_cd = '00A'

SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
  FROM bt_dc_document_library
  WHERE status_cd = '00A'
    AND tenant_id = #{dto.tenantId}
    AND library_name = #{dto.libraryName}

    AND library_id != #{dto.libraryId}
